import numpy as np

def qmul(p, q):
    """Hamilton product of quaternions stored as (w, x, y, z)."""
    pw, pv, qw, qv = p[0], np.asarray(p[1:]), q[0], np.asarray(q[1:])
    return np.concatenate([[pw * qw - pv @ qv], pw * qv + qw * pv + np.cross(pv, qv)])

def rpy_to_quat(roll, pitch, yaw):
    """Unit quaternion (w, x, y, z), with w >= 0, for R = Rz(yaw) @ Ry(pitch) @ Rx(roll)."""
    return np.array([1.0, 0.0, 0.0, 0.0])

exercises.tests:
import numpy as np

def _Rx(a):
    c, s = np.cos(a), np.sin(a)
    return np.array([[1, 0, 0], [0, c, -s], [0, s, c]])

def _Ry(a):
    c, s = np.cos(a), np.sin(a)
    return np.array([[c, 0, s], [0, 1, 0], [-s, 0, c]])

def _Rz(a):
    c, s = np.cos(a), np.sin(a)
    return np.array([[c, -s, 0], [s, c, 0], [0, 0, 1]])

def _q_to_R(q):
    w, x, y, z = q
    return np.array([[1 - 2 * (y * y + z * z), 2 * (x * y - w * z), 2 * (x * z + w * y)],
                     [2 * (x * y + w * z), 1 - 2 * (x * x + z * z), 2 * (y * z - w * x)],
                     [2 * (x * z - w * y), 2 * (y * z + w * x), 1 - 2 * (x * x + y * y)]])

q = np.asarray(rpy_to_quat(0.0, 0.0, np.pi / 2), dtype=float)
assert q.shape == (4,), "return four numbers (w, x, y, z)"
assert np.allclose(q, [np.sqrt(0.5), 0, 0, np.sqrt(0.5)]), f"yaw of 90 degrees is (cos 45, 0, 0, sin 45), got {q}"
q = np.asarray(rpy_to_quat(np.pi / 2, 0.0, 0.0), dtype=float)
assert np.allclose(q, [np.sqrt(0.5), np.sqrt(0.5), 0, 0]), "roll of 90 degrees is about x"
_rng = np.random.default_rng(3)
for _ in range(200):
    r, p, y = _rng.uniform(-np.pi, np.pi), _rng.uniform(-np.pi / 2, np.pi / 2), _rng.uniform(-np.pi, np.pi)
    q = np.asarray(rpy_to_quat(r, p, y), dtype=float)
    assert np.isclose(np.linalg.norm(q), 1.0), "the quaternion must have unit length"
    assert q[0] >= 0, "choose the sign with w >= 0"
    assert np.allclose(_q_to_R(q), _Rz(y) @ _Ry(p) @ _Rx(r), atol=1e-9), "the order must match Rz(yaw) Ry(pitch) Rx(roll)"

