import numpy as np

def slerp(p, q, t):
    """Spherical linear interpolation between unit quaternions p and q (w, x, y, z), 0 <= t <= 1.
    Take the shorter way round, and do not divide by zero when p and q are (nearly) equal."""
    r = (1 - t) * np.asarray(p, float) + t * np.asarray(q, float)
    return r / np.linalg.norm(r)

